-- ── levels ─────────────────────────────────────────────────────────────
-- The rank of a level within its process, lowest first; -1 when unknown.
create or replace function public.setup_level_rank(p_process text, p_level text)
returns int language sql immutable set search_path = public as $fn$
  select coalesce((
    select (o - 1)::int
      from jsonb_array_elements(public.setup_level_catalogue()->'processes') p,
           jsonb_array_elements(p->'levels') with ordinality y(l, o)
     where p->>'process' = p_process and l->>'level' = p_level), -1);
$fn$;
revoke execute on function public.setup_level_rank(text, text) from public, anon, authenticated;

-- Each process's level as the stored features say (the app's
-- currentSetupLevels): the highest level whose features and those of every
-- level below it are all on, else the lowest.
create or replace function public.setup_current_levels(p_flags jsonb)
returns jsonb language sql stable set search_path = public as $fn$
  select coalesce(jsonb_agg(jsonb_build_object('process', p->>'process', 'level',
    coalesce((select l->>'level'
                from jsonb_array_elements(p->'levels') with ordinality x(l, i)
               where not exists (
                 select 1
                   from jsonb_array_elements(p->'levels') with ordinality y(below, j)
                   cross join lateral jsonb_array_elements_text(below->'features') f
                  where j <= i and not public.feature_raw(p_flags, f))
               order by i desc limit 1),
             p->'levels'->0->>'level')) order by pi), '[]'::jsonb)
    from jsonb_array_elements(public.setup_level_catalogue()->'processes') with ordinality q(p, pi);
$fn$;
revoke execute on function public.setup_current_levels(jsonb) from public, anon, authenticated;

-- The arguments a level choice may carry: a preset and one level per process.
create or replace function public.setup_level_arguments()
returns text[] language sql immutable set search_path = public as $fn$
  select array['workspace_id', 'request_id', 'preset']
         || array(select p->>'process' from jsonb_array_elements(public.setup_level_catalogue()->'processes') p);
$fn$;
revoke execute on function public.setup_level_arguments() from public, anon, authenticated;

-- An assistant's arguments for a setup operation: a name a credential goes
-- by is refused outright (DKS01), whatever the operation would do with it;
-- any other name the operation does not take is invalid.
create or replace function public.mcp_setup_arguments(p_args jsonb, p_allowed text[])
returns void language plpgsql immutable set search_path = public as $fn$
begin
  if exists (select 1 from jsonb_object_keys(coalesce(p_args, '{}'::jsonb)) k
              where k ~* '(secret|password|passphrase|api_?key|access_?key|private_?key|token|credential|signing)') then
    raise exception 'credentials are entered in the DesKilo app by the person, never by an assistant'
      using errcode = 'DKS01';
  end if;
  if exists (select 1 from jsonb_object_keys(coalesce(p_args, '{}'::jsonb)) k where not (k = any (p_allowed))) then
    raise exception 'unknown argument' using errcode = '22023';
  end if;
end;
$fn$;
revoke execute on function public.mcp_setup_arguments(jsonb, text[]) from public, anon, authenticated;

-- What choosing levels changes (the app's planSetupLevels): only processes
-- whose level differs take part; a preset is overridden by a process named
-- beside it; gaps are read over the whole resulting vector. `flags` and
-- `expected` are set_feature_flags' delta and read-set; `revision` is the
-- stored features it was computed from.
create or replace function public.setup_levels_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_cat jsonb := public.setup_level_catalogue();
  v_flags jsonb;
  v_current jsonb;
  v_chosen jsonb;
  v_preset jsonb;
  v_changes jsonb := '[]'::jsonb;
  v_gaps jsonb := '[]'::jsonb;
  v_on text[] := '{}';
  v_off text[] := '{}';
  v_switch_on text[];
  v_switch_off text[];
  v_process text;
  v_changed boolean;
  v_rank int;
  p jsonb;
  l jsonb;
  i int;
begin
  perform public.mcp_setup_arguments(p_args, public.setup_level_arguments());
  select coalesce(feature_flags, '{}'::jsonb) into v_flags from public.workspaces where id = p_workspace_id;
  if not found then
    raise exception 'unknown workspace' using errcode = '22023';
  end if;
  select coalesce(jsonb_object_agg(e->>'process', e->>'level'), '{}'::jsonb) into v_current
    from jsonb_array_elements(public.setup_current_levels(v_flags)) e;
  v_chosen := v_current;
  if p_args ? 'preset' then
    select pr->'levels' into v_preset from jsonb_array_elements(v_cat->'presets') pr
     where pr->>'preset' = p_args->>'preset';
    if v_preset is null then
      raise exception 'unknown preset %', p_args->>'preset' using errcode = '22023';
    end if;
    select v_chosen || coalesce(jsonb_object_agg(e->>'process', e->>'level'), '{}'::jsonb) into v_chosen
      from jsonb_array_elements(v_preset) e;
  end if;
  for p in select x from jsonb_array_elements(v_cat->'processes') x loop
    v_process := p->>'process';
    if p_args ? v_process then
      if public.setup_level_rank(v_process, p_args->>v_process) < 0 then
        raise exception 'unknown level % of %', p_args->>v_process, v_process using errcode = '22023';
      end if;
      v_chosen := v_chosen || jsonb_build_object(v_process, p_args->>v_process);
    end if;
  end loop;
  for p in select x from jsonb_array_elements(v_cat->'processes') x loop
    v_process := p->>'process';
    v_rank := public.setup_level_rank(v_process, v_chosen->>v_process);
    v_changed := v_chosen->>v_process is distinct from v_current->>v_process;
    if v_changed then
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'process', v_process, 'from', v_current->>v_process, 'to', v_chosen->>v_process));
    end if;
    for l, i in select y.l, (y.o - 1)::int from jsonb_array_elements(p->'levels') with ordinality y(l, o) loop
      -- a level carries the needs of the levels below it: their features are on too
      if i <= v_rank then
        v_gaps := v_gaps || coalesce((
          select jsonb_agg(jsonb_build_object('process', v_process, 'level', l->>'level', 'needs', n))
            from jsonb_array_elements(l->'needs') n
           where public.setup_level_rank(n->>'process', v_chosen->>(n->>'process'))
                 < public.setup_level_rank(n->>'process', n->>'level')), '[]'::jsonb);
      end if;
      if v_changed then
        if i <= v_rank then
          v_on := v_on || array(select jsonb_array_elements_text(l->'features'));
        else
          v_off := v_off || array(select jsonb_array_elements_text(l->'features'));
        end if;
      end if;
    end loop;
  end loop;
  v_switch_on := array(select f from unnest(v_on) with ordinality u(f, o)
                        where not public.feature_raw(v_flags, f) group by f order by min(o));
  v_switch_off := array(select f from unnest(v_off) with ordinality u(f, o)
                         where public.feature_raw(v_flags, f) group by f order by min(o));
  return jsonb_build_object(
    'current', public.setup_current_levels(v_flags),
    'changes', v_changes,
    'switch_on', to_jsonb(v_switch_on),
    'switch_off', to_jsonb(v_switch_off),
    'gaps', v_gaps,
    'ready_to_apply', jsonb_array_length(v_gaps) = 0 and cardinality(v_switch_on) + cardinality(v_switch_off) > 0,
    -- off wins over on, as in the app's delta
    'flags', coalesce((select jsonb_object_agg(f, true) from unnest(v_switch_on) f), '{}'::jsonb)
             || coalesce((select jsonb_object_agg(f, false) from unnest(v_switch_off) f), '{}'::jsonb),
    'expected', coalesce((select jsonb_object_agg(f, public.feature_raw(v_flags, f))
                            from unnest(v_switch_on || v_switch_off) f), '{}'::jsonb),
    'revision', md5(v_flags::text));
end;
$fn$;
revoke execute on function public.setup_levels_plan(uuid, jsonb) from public, anon, authenticated;

-- ── steps ──────────────────────────────────────────────────────────────
-- Whether a step takes a credential (the step catalogue's `secret`).
create or replace function public.setup_step_holds_secret(p_step text)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce((select (s->>'secret')::boolean from jsonb_array_elements(public.setup_step_catalogue()) s
                    where s->>'id' = p_step), false);
$fn$;
revoke execute on function public.setup_step_holds_secret(text) from public, anon, authenticated;

-- The step's status when an acknowledgement may be written for it (0545's
-- rules, unchanged): a required step the server verifies cannot be set
-- aside, and a step with nothing left to do cannot either.
create or replace function public.setup_step_markable(p_workspace_id uuid, p_step text)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_step jsonb;
begin
  select e into v_step from jsonb_array_elements(public.workspace_setup_status(p_workspace_id)->'steps') e
   where e->>'step' = p_step limit 1;
  if v_step is null then
    raise exception 'the setup guide has no step %', coalesce(p_step, '(none)')
      using errcode = '22023';
  end if;
  if coalesce((v_step->>'required')::boolean, false)
     and not coalesce((v_step->>'manual')::boolean, false) then
    raise exception 'a required step cannot be set aside for later: it has to be set up'
      using errcode = '22023';
  end if;
  if v_step->>'state' in ('ready', 'not_applicable', 'deferred') then
    raise exception 'this step has nothing left to set aside' using errcode = '22023';
  end if;
  return v_step;
end;
$fn$;
revoke execute on function public.setup_step_markable(uuid, text) from public, anon, authenticated;

-- The acknowledgement itself, for the caller; who may call it is the
-- caller's business (acknowledge_setup_step in the app, the confirmed MCP
-- operation for an assistant).
create or replace function public.setup_step_acknowledge(p_workspace_id uuid, p_step text)
returns public.readiness_acknowledgements language plpgsql volatile security definer set search_path = public as $fn$
declare
  v_step jsonb := public.setup_step_markable(p_workspace_id, p_step);
  v public.readiness_acknowledgements;
begin
  insert into public.readiness_acknowledgements (workspace_id, user_id, section, material_revision)
  values (p_workspace_id, auth.uid(), p_step, md5(p_step || ':' || coalesce(v_step->>'state', '')))
  on conflict on constraint readiness_acknowledgements_key do update
    set material_revision = excluded.material_revision, acknowledged_at = now()
  returning * into v;
  return v;
end;
$fn$;
revoke execute on function public.setup_step_acknowledge(uuid, text) from public, anon, authenticated;

-- 0545's command, unchanged in what it allows: manageConfiguration, never a
-- delegated assistant token.
create or replace function public.acknowledge_setup_step(p_workspace_id uuid, p_step text)
returns public.readiness_acknowledgements language plpgsql volatile security definer set search_path = public as $fn$
begin
  if auth.uid() is null or public.mcp_is_delegated()
     or not public.has_permission(p_workspace_id, 'manageConfiguration') then
    raise exception 'only someone who configures this workspace sets a step aside'
      using errcode = '42501';
  end if;
  return public.setup_step_acknowledge(p_workspace_id, p_step);
end;
$fn$;
revoke execute on function public.acknowledge_setup_step(uuid, text) from public, anon;
grant execute on function public.acknowledge_setup_step(uuid, text) to authenticated;

-- ── the confirmation ───────────────────────────────────────────────────
-- What a confirmed operation is about: its own mcp_target_<id> when it has
-- one, else the shared mcp_target.
create or replace function public.mcp_target_of(p_workspace_id uuid, p_operation text, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  if to_regprocedure(format('public.%I(uuid, jsonb)', 'mcp_target_' || p_operation)) is null then
    return public.mcp_target(p_workspace_id, p_operation, p_args);
  end if;
  execute format('select public.%I($1, $2)', 'mcp_target_' || p_operation) into v using p_workspace_id, p_args;
  return v;
end;
$fn$;
revoke execute on function public.mcp_target_of(uuid, text, jsonb) from public, anon, authenticated;

-- Refused before anyone is asked: the setup guide off (42501), a
-- credential (DKS01), a choice with a gap or no change (22023).
create or replace function public.mcp_target_apply_setup_levels(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  if not public.feature_effective(p_workspace_id, 'setupGuide') then
    raise exception 'the setup guide is off in this workspace' using errcode = '42501';
  end if;
  v := public.setup_levels_plan(p_workspace_id, p_args);
  if jsonb_array_length(v->'gaps') > 0 then
    raise exception 'a chosen level needs a higher level of another process' using errcode = '22023';
  end if;
  if v->'flags' = '{}'::jsonb then
    raise exception 'the chosen levels change nothing' using errcode = '22023';
  end if;
  return jsonb_build_object('kind', 'setup_levels', 'changes', v->'changes',
    'switch_on', v->'switch_on', 'switch_off', v->'switch_off', 'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_apply_setup_levels(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_mark_setup_step(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_step jsonb;
begin
  if not public.feature_effective(p_workspace_id, 'setupGuide') then
    raise exception 'the setup guide is off in this workspace' using errcode = '42501';
  end if;
  perform public.mcp_setup_arguments(p_args, array['workspace_id', 'request_id', 'step']);
  if public.setup_step_holds_secret(p_args->>'step') then
    raise exception 'this step takes credentials: the person enters them in the DesKilo app'
      using errcode = 'DKS01';
  end if;
  v_step := public.setup_step_markable(p_workspace_id, p_args->>'step');
  return jsonb_build_object('kind', 'setup_step', 'step', v_step->>'step', 'state', v_step->>'state',
    'marked', case when (v_step->>'manual')::boolean then 'done' else 'set_aside' end,
    'revision', md5(v_step::text));
end;
$fn$;
revoke execute on function public.mcp_target_mark_setup_step(uuid, jsonb) from public, anon, authenticated;

-- 0412's native confirmation, whole; the target now comes from
-- mcp_target_of, and a credential or an absent feature is refused as such.
create or replace function public.mcp_confirm(c public.mcp_call_context, p_request_id uuid, p_digest text, p_args jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_confirmation public.mcp_action_confirmations;
  v_target jsonb;
begin
  select * into v_confirmation from public.mcp_action_confirmations
   where installation_id = public.installation_id() and local_user_id = auth.uid()
     and client_id = c.client_id and request_id = p_request_id
   for update;
  begin
    v_target := public.mcp_target_of(c.workspace_id, c.operation, p_args);
  exception
    when sqlstate 'DKS01' then
      return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
        'denied', null, 'secret_in_app_only'));
    when insufficient_privilege then
      return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
        'denied', null, 'not_exposed'));
    when invalid_parameter_value or invalid_text_representation then
      return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
        'validation_error', null, 'invalid_arguments'));
  end;
  if v_target is null then
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'not_found', null, 'not_found'));
  end if;
  if v_confirmation.id is null then
    insert into public.mcp_action_confirmations (installation_id, local_user_id, client_id,
      workspace_id, eligibility_grant_id, operation, request_id, args_digest, target_revision, preview)
    values (public.installation_id(), auth.uid(), c.client_id, c.workspace_id, c.grant_id,
            c.operation, p_request_id, p_digest, coalesce(v_target->>'revision', ''),
            jsonb_build_object('arguments', p_args - 'request_id', 'target', v_target - 'revision'))
    returning * into v_confirmation;
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'requires_confirmation',
      jsonb_build_object('confirmation_id', v_confirmation.id, 'expires_at', v_confirmation.expires_at)));
  end if;
  if v_confirmation.workspace_id <> c.workspace_id or v_confirmation.operation <> c.operation
     or v_confirmation.args_digest <> p_digest then
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'conflict', null, 'request_id_reused'));
  end if;
  if v_confirmation.eligibility_grant_id <> c.grant_id
     or coalesce(v_target->>'revision', '') <> v_confirmation.target_revision then
    update public.mcp_action_confirmations set status = 'revoked'
     where id = v_confirmation.id and status in ('pending', 'acknowledged');
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'conflict', null, 'confirmation_stale'));
  end if;
  if v_confirmation.status = 'pending' and v_confirmation.expires_at > now() then
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'requires_confirmation',
      jsonb_build_object('confirmation_id', v_confirmation.id, 'expires_at', v_confirmation.expires_at)));
  end if;
  if v_confirmation.status <> 'acknowledged' or v_confirmation.expires_at <= now() then
    return public.mcp_usage_note(c.spec, public.mcp_envelope(p_request_id, c.operation, c.workspace_id,
      'denied', null,
      case when v_confirmation.status = 'declined' then 'confirmation_declined' else 'confirmation_expired' end));
  end if;
  update public.mcp_action_confirmations set status = 'consumed', consumed_at = now()
   where id = v_confirmation.id;
  return null;
end;
$fn$;
revoke execute on function public.mcp_confirm(public.mcp_call_context, uuid, text, jsonb) from public, anon, authenticated;

-- 0272's answer from the app, whole; the target it re-reads now comes from
-- mcp_target_of, so an operation with its own target is checked by it.
create or replace function public.mcp_confirm_action(p_confirmation_id uuid, p_accept boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $fn$
declare
  v_c public.mcp_action_confirmations;
  v_spec jsonb;
  v_target jsonb;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if auth.jwt() ? 'client_id' then raise exception 'confirmations are answered in the Deskilo app'; end if;
  select * into v_c from public.mcp_action_confirmations
   where id = p_confirmation_id and local_user_id = auth.uid() for update;
  if v_c.id is null then return jsonb_build_object('status', 'not_found'); end if;
  if v_c.status <> 'pending' then return jsonb_build_object('status', v_c.status); end if;
  if v_c.expires_at <= now() then
    update public.mcp_action_confirmations set status = 'expired' where id = v_c.id;
    return jsonb_build_object('status', 'expired');
  end if;
  if not p_accept then
    update public.mcp_action_confirmations set status = 'declined' where id = v_c.id;
    return jsonb_build_object('status', 'declined');
  end if;
  -- Everything the action will need is checked again now.
  if not exists (select 1 from public.mcp_eligibility_grants
                  where id = v_c.eligibility_grant_id and status = 'active' and expires_at > now()) then
    update public.mcp_action_confirmations set status = 'revoked' where id = v_c.id;
    return jsonb_build_object('status', 'revoked');
  end if;
  perform public.my_active_member(v_c.workspace_id);
  v_spec := public.mcp_operation_catalogue()->'operations'->v_c.operation;
  if v_spec->>'authority' = 'permission'
     and not public.has_permission(v_c.workspace_id, v_spec->>'permission') then
    update public.mcp_action_confirmations set status = 'revoked' where id = v_c.id;
    return jsonb_build_object('status', 'revoked');
  end if;
  -- A target that can no longer be read (its operation now refuses the
  -- arguments) has changed as far as this confirmation is concerned.
  begin
    v_target := public.mcp_target_of(v_c.workspace_id, v_c.operation, v_c.preview->'arguments');
  exception when sqlstate 'DKS01' or insufficient_privilege or invalid_parameter_value
                 or invalid_text_representation then
    v_target := null;
  end;
  if coalesce(v_target->>'revision', '') <> v_c.target_revision then
    update public.mcp_action_confirmations set status = 'revoked' where id = v_c.id;
    return jsonb_build_object('status', 'target_changed');
  end if;
  update public.mcp_action_confirmations set status = 'acknowledged', acknowledged_at = now()
   where id = v_c.id;
  return jsonb_build_object('status', 'acknowledged');
end;
$fn$;
revoke execute on function public.mcp_confirm_action(uuid, boolean) from public, anon;
grant execute on function public.mcp_confirm_action(uuid, boolean) to authenticated;

-- ── handlers ───────────────────────────────────────────────────────────
-- A setup operation's refusal before it runs, or null: the setup guide off
-- in this workspace, or a credential among the arguments.
create or replace function public.mcp_setup_refusal(p_workspace_id uuid, p_args jsonb, p_allowed text[])
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
begin
  if not public.feature_effective(p_workspace_id, 'setupGuide') then
    return public.mcp_outcome('denied', null, 'not_exposed');
  end if;
  perform public.mcp_setup_arguments(p_args, p_allowed);
  return null;
exception when sqlstate 'DKS01' then
  return public.mcp_outcome('denied', null, 'secret_in_app_only');
end;
$fn$;
revoke execute on function public.mcp_setup_refusal(uuid, jsonb, text[]) from public, anon, authenticated;

create or replace function public.mcp_op_get_setup_status(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id']);
  v_status jsonb;
  v_steps jsonb;
  v_next_milestone text;
  v_next_rank bigint;
  v_next_step text;
begin
  if v_refusal is not null then return v_refusal; end if;
  v_status := public.workspace_setup_status(c.workspace_id);
  -- The first milestone this space has chosen and not reached (the app's
  -- SetupStatus.nextMilestone).
  select m->>'milestone', o into v_next_milestone, v_next_rank
    from jsonb_array_elements(v_status->'milestones') with ordinality x(m, o)
   where (m->>'applies')::boolean and not (m->>'reached')::boolean
   order by o limit 1;
  -- What an assistant may do with each step: a step with a credential only
  -- in the app; a step only the person can tell is done marked done; an
  -- optional one set aside; anything else done by the person on its screen.
  select coalesce(jsonb_agg(s || jsonb_build_object('assistant', case
           when public.setup_step_holds_secret(s->>'step') then 'in_app_only'
           when s->>'state' in ('ready', 'not_applicable', 'deferred') then 'none'
           when (s->>'manual')::boolean then 'mark_done'
           when not (s->>'required')::boolean then 'set_aside'
           else 'in_app' end) order by i), '[]'::jsonb)
    into v_steps
    from jsonb_array_elements(v_status->'steps') with ordinality x(s, i);
  -- The one next action (the app's SetupStatus.nextStep): what the next
  -- milestone needs, else what a later one needs, else an optional step.
  select s->>'step' into v_next_step
    from jsonb_array_elements(v_status->'steps') with ordinality x(s, i)
   where s->>'state' = 'needs_configuration'
   order by case
              when (s->>'required')::boolean and v_next_rank is not null
                   and (select o from jsonb_array_elements(v_status->'milestones') with ordinality y(m, o)
                         where m->>'milestone' = s->>'milestone') <= v_next_rank then 0
              when (s->>'required')::boolean then 1
              else 2 end, i
   limit 1;
  return public.mcp_outcome('completed', jsonb_build_object(
    'steps', v_steps,
    'milestones', v_status->'milestones',
    'next_milestone', v_next_milestone,
    'next_step', v_next_step,
    'levels', public.setup_current_levels(
      (select coalesce(feature_flags, '{}'::jsonb) from public.workspaces where id = c.workspace_id))));
end;
$fn$;

create or replace function public.mcp_op_list_setup_levels(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id']);
begin
  if v_refusal is not null then return v_refusal; end if;
  return public.mcp_outcome('completed', public.setup_level_catalogue() || jsonb_build_object(
    'current', public.setup_current_levels(
      (select coalesce(feature_flags, '{}'::jsonb) from public.workspaces where id = c.workspace_id))));
end;
$fn$;

create or replace function public.mcp_op_preview_setup_levels(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, public.setup_level_arguments());
  v jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  v := public.setup_levels_plan(c.workspace_id, p_args);
  return public.mcp_outcome('completed', jsonb_build_object('changes', v->'changes',
    'switch_on', v->'switch_on', 'switch_off', v->'switch_off', 'gaps', v->'gaps',
    'ready_to_apply', v->'ready_to_apply'));
end;
$fn$;

-- Runs only after the person confirmed the exact change (mcp_confirm), and
-- writes it as the app does: the delta against its read-set, so a change
-- in the meantime is refused, never overwritten.
create or replace function public.mcp_op_apply_setup_levels(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, public.setup_level_arguments());
  v jsonb;
begin
  if v_refusal is not null then return v_refusal; end if;
  v := public.setup_levels_plan(c.workspace_id, p_args);
  if jsonb_array_length(v->'gaps') > 0 then
    return public.mcp_outcome('validation_error', null, 'invalid_arguments');
  end if;
  if v->'flags' = '{}'::jsonb then
    return public.mcp_outcome('completed', jsonb_build_object('unchanged', true, 'changes', '[]'::jsonb,
      'levels', v->'current'));
  end if;
  begin
    perform public.set_feature_flags(c.workspace_id, v->'flags', v->'expected');
  exception when sqlstate 'DK409' then
    return public.mcp_outcome('conflict', null, 'confirmation_stale');
  end;
  return public.mcp_outcome('completed', jsonb_build_object('changes', v->'changes',
    'switch_on', v->'switch_on', 'switch_off', v->'switch_off',
    'levels', public.setup_current_levels(
      (select coalesce(feature_flags, '{}'::jsonb) from public.workspaces where id = c.workspace_id))));
end;
$fn$;

-- Runs only after the person confirmed it, under 0545's rules; a step that
-- takes credentials is refused here too, whatever reached the handler.
create or replace function public.mcp_op_mark_setup_step(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id', 'step']);
  v_step text := p_args->>'step';
  v_manual boolean;
begin
  if v_refusal is not null then return v_refusal; end if;
  if public.setup_step_holds_secret(v_step) then
    return public.mcp_outcome('denied', null, 'secret_in_app_only');
  end if;
  v_manual := (public.setup_step_markable(c.workspace_id, v_step)->>'manual')::boolean;
  perform public.setup_step_acknowledge(c.workspace_id, v_step);
  return public.mcp_outcome('completed', jsonb_build_object('step', v_step,
    'state', (select e->>'state' from jsonb_array_elements(public.workspace_setup_status(c.workspace_id)->'steps') e
               where e->>'step' = v_step limit 1),
    'marked', case when v_manual then 'done' else 'set_aside' end));
end;
$fn$;

-- Every handler is reached only through mcp_execute_v1.
revoke execute on function public.mcp_op_get_setup_status(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_list_setup_levels(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_preview_setup_levels(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_apply_setup_levels(public.mcp_call_context, jsonb) from public, anon, authenticated;
revoke execute on function public.mcp_op_mark_setup_step(public.mcp_call_context, jsonb) from public, anon, authenticated;

notify pgrst, 'reload schema';

select public.set_deskilo_schema_version(555);
